class Solution:
    def longestPiece(self, ropes: List[int], pieces: int) -> float:
        best = 0.0
        for r in ropes:
            for m in range(1, pieces + 1):
                count = sum(x * m // r for x in ropes)
                if count >= pieces:
                    best = max(best, r / m)
        return best

