class Solution {
    public double longestPiece(int[] ropes, int pieces) {
        double best = 0;
        for (int r : ropes) {
            for (int m = 1; m <= pieces; m++) {
                long count = 0;
                for (int x : ropes) count += (long) x * m / r;
                if (count >= pieces) best = Math.max(best, (double) r / m);
            }
        }
        return best;
    }
}

