double longestPiece(int* ropes, int ropesSize, int pieces) {
    double best = 0;
    for (int i = 0; i < ropesSize; i++) {
        for (int m = 1; m <= pieces; m++) {
            long long count = 0;
            for (int j = 0; j < ropesSize; j++) count += (long long) ropes[j] * m / ropes[i];
            if (count >= pieces && (double) ropes[i] / m > best) best = (double) ropes[i] / m;
        }
    }
    return best;
}

