class Solution:
    def longestPiece(self, ropes: List[int], pieces: int) -> float:
        lo, hi = 0.0, float(max(ropes))
        for _ in range(100):
            mid = (lo + hi) / 2
            if sum(int(r / mid) for r in ropes) >= pieces:
                lo = mid
            else:
                hi = mid
        return lo

